pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint unlockTime, uint putAmount, uint collectAmount) public {
        // Bound inputs to avoid overflows and maintain contract invariants
        vm.assume(caller != address(0));
        putAmount = bound(putAmount, 0, 100 ether);
        collectAmount = bound(collectAmount, 0, putAmount);
        unlockTime = bound(unlockTime, 0, 365 days);

        // Set up caller and time
        vm.deal(caller, putAmount);
        vm.warp(block.timestamp + unlockTime + 1); // Ensure unlock time passes

        // Record total balance before
        uint beforeBalance = address(c).balance;

        // Call Put to add funds
        vm.prank(caller);
        c.Put{value: putAmount}(unlockTime);

        // Call Collect to withdraw
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // Record total balance after
        uint afterBalance = address(c).balance;

        // General rule: total contract balance should never increase after any Collect attempt
        // (It may stay same if Collect reverts or decreases if successful)
        assertTrue(afterBalance <= beforeBalance + putAmount);
    }
}

