pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 depositAmount, uint256 unlockTime, uint256 withdrawAmount) public {
        // Bound inputs to avoid overflow and unrealistic values
        depositAmount = bound(depositAmount, 0, 100 ether);
        unlockTime = bound(unlockTime, 0, type(uint40).max); // reasonable timestamp
        withdrawAmount = bound(withdrawAmount, 0, 100 ether);

        // Fund the test contract to be able to send value
        vm.deal(address(this), 1000 ether);

        // Get initial contract balance
        uint256 initialContractBalance = address(c).balance;

        // Make a deposit via Put
        c.Put{value: depositAmount}(unlockTime);

        // Record caller's balance before Collect
        uint256 callerBalanceBefore = address(this).balance;

        // Attempt Collect
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, withdrawAmount));

        // After Collect
        uint256 callerBalanceAfter = address(this).balance;
        uint256 contractBalanceAfter = address(c).balance;

        // Get caller's stored balance from the contract
        (uint256 storedUnlockTime, uint256 storedBalance) = c.Acc(address(this));

        if (success) {
            // Successful Collect: caller balance decreases by withdrawAmount, contract balance decreases by withdrawAmount
            assertTrue(callerBalanceBefore - callerBalanceAfter == withdrawAmount, "Caller balance reduction mismatch");
            assertTrue(contractBalanceAfter + withdrawAmount == initialContractBalance + depositAmount, "Contract balance reduction mismatch");
        } else {
            // Reverted Collect: balances unchanged
            assertTrue(callerBalanceBefore == callerBalanceAfter, "Caller balance unchanged on revert");
            assertTrue(contractBalanceAfter == initialContractBalance + depositAmount, "Contract balance unchanged on revert");
        }
    }
}

