contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime, uint256 collectAmount) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.assume(collectAmount > 0);
        vm.assume(unlockTime > block.timestamp); // ensure unlock time is in future

        uint256 initialContractBalance = address(c).balance;
        // Simulate a deposit via Put
        vm.deal(address(this), amount);
        (bool success, ) = address(c).call{value: amount}(abi.encodeWithSignature("Put(uint256)", unlockTime));
        vm.assume(success);

        // Now push time forward so we can collect
        vm.warp(unlockTime + 1);

        // Attempt collect
        (bool collectSuccess, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The rule: after collect, contract balance + sum of all Acc balances equals initial balance + total deposits
        // Since we only deposited once, total deposits = amount
        uint256 totalDeposits = amount;
        uint256 expectedTotal = initialContractBalance + totalDeposits;

        // Sum balances: we can only read public mapping Acc, which is a mapping(address => Holder) with fields unlockTime and balance
        // We need to sum all balances but we don't know caller address in this setup; we can track via the caller
        address caller = address(this);
        ( , uint256 callerBalance) = c.Acc(caller);

        // Contract balance may have changed if collect succeeded
        uint256 contractBalanceAfter = address(c).balance;

        // The sum of all Acc balances is at least callerBalance (others unknown), but we can bound by total deposits
        // Since only this caller deposited, the sum should be <= totalDeposits
        uint256 sumAccBalances = callerBalance;

        assertTrue(address(c).balance + sumAccBalances == initialContractBalance + amount);
    }
}

