pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime, uint256 deposit, uint256 withdraw) public {
        vm.assume(deposit > 0 && deposit <= 10 ether);
        vm.assume(withdraw <= deposit);

        address user = address(0x1234);
        vm.deal(user, 100 ether);

        // User makes a deposit via Put
        vm.prank(user);
        c.Put{value: deposit}(unlockTime);

        // Now user attempts to collect
        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", withdraw));

        // Regardless of success, the invariant: user's balance cannot exceed what was unlocked
        (uint256 storedTime, uint256 balance) = c.Acc(user);

        // The unlockTime must have been set to block.timestamp in the buggy version, 
        // but in the reference it could be the provided unlockTime if that is > block.timestamp.
        // The invariant: if Collect succeeded, then block.timestamp > storedTime.
        // But we can't guarantee success; we can only check that if success then storedTime < block.timestamp.
        // More generally, the bug changes storedTime to block.timestamp always, breaking the invariant
        // that storedTime >= block.timestamp (since the reference ensures storedTime >= block.timestamp).
        // We assert that storedTime >= block.timestamp.
        assertTrue(storedTime >= block.timestamp, "unlockTime should be >= block.timestamp");
    }
}

