pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint256 unlockTime, uint256 putAmount, uint256 collectAmount) public {
        // restrict collectAmount to be exactly the putAmount put in
        putAmount = bound(putAmount, 1 ether, 1e26);
        collectAmount = bound(collectAmount, 1 ether, putAmount);
        // ensure unlockTime is in the past so that after put, balance >= MinSum, and we can target the equality on timestamp
        unlockTime = bound(unlockTime, 0, block.timestamp - 1);
        vm.deal(user, putAmount);
        vm.prank(user);
        c.Put{value: putAmount}(unlockTime);
        // now warp to exactly the unlockTime (which is <= block.timestamp after warp, but we set it earlier)
        // To test equality case, we set unlockTime to a value that after Put may be block.timestamp or earlier.
        // Since Put sets unlockTime = max(unlockTime, block.timestamp), we need to ensure it becomes exactly block.timestamp.
        // Call Put with unlockTime = 0, then the unlockTime becomes block.timestamp. Then warp to that same timestamp.
        // But we already called Put; we can call Put again with unlockTime = 0.
        vm.prank(user);
        c.Put{value: 0}(0); // this sets unlockTime = block.timestamp
        // Now warp to block.timestamp (which is the unlockTime)
        vm.warp(block.timestamp);
        // Now call Collect with exactly putAmount (since we put at least that)
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", collectAmount));
        // The rule: reference C reverts when block.timestamp == unlockTime, buggy M does not
        assertTrue(!success, "Collect should revert when block.timestamp == unlockTime");
    }
}

